args.new_string:
// Async server component — no 'use cache' since user preferences are
// per-request data that should never be served from a shared cache.
// The parent page wraps this component in <Suspense> so Next.js streams
// the fallback while the fetch resolves at request time.
export default async function UserDashboard() {
  const res = await fetch('/api/user/preferences', { cache: 'no-store' });

  if (!res.ok) {
    throw new Error(`Failed to load preferences: ${res.status}`);
  }

  const preferences: {
    theme: string;
    language: string;
    notifications: boolean;
  } = await res.json();

  return (
    <div>
      <h2>User Dashboard</h2>
      <ul>
        <li>Theme: {preferences.theme}</li>
        <li>Language: {preferences.language}</li>
        <li>Notifications: {preferences.notifications ? 'On' : 'Off'}</li>
      </ul>
    </div>
  );
}

